// Кейс: .qa/tests/camera-aim/CAM-004.md · план: .qa/e2e-app/specs/app.md (1.53)
// Android, бледная вода («תכלת» с брызгами) проходит: нет «לא זוהו מים…»/«בהירים מהרגיל»/«זו הבריכה שלי», галочка → «המשך» активна.
// Цвет точек (зелёный) и рамки — по скриншоту, вручную (uiautomator цвет не видит).
// РУЧНАЯ СЦЕНА (требует подготовки): камера Pixel смотрит на экран Mac (Safari на весь экран, яркость фиксированная), на нём на весь экран
// .qa/media/girl-swimming-oblique.mp4; 4 точки вокруг воды (автоконтур или руками). BANCI_SCENE=pool-pale (иначе пропуск). Шаг 1 → BANCI_SOUND=1.
// Мониторинг НЕ запускается («המשך» не нажимается).
import { assert, skip, openCameraStep, checkWaterBox, NO_WATER_HINT, OLD_POOL_CHECKBOX, PALE_HINT } from '../lib.mjs';

export const name = 'Android шаг 2, бледная вода (видео бассейна): без «לא זוהו מים»/«בהירים מהרגיל»/«זו הבריכה שלי», галочка → «המשך» активна (ручная сцена BANCI_SCENE=pool-pale) #ab4270 @android @app';

export default async function (app) {
  if (!['pool-pale', 'water'].includes(process.env.BANCI_SCENE)) skip('ручная сцена: на Mac на весь экран .qa/media/girl-swimming-oblique.mp4, камера Pixel на экран, 4 точки вокруг воды → BANCI_SCENE=pool-pale');

  await openCameraStep(app);
  assert(!(await app.exists(OLD_POOL_CHECKBOX)), 'нет галочки «זו הבריכה שלי» (OTA c38476a1 не загрузился?)');
  await checkWaterBox(app);
  await app.waitEnabled('המשך', true, { timeout: 20000, what: '«המשך» на бледной воде с галочкой (если серая — смотреть подсказку на экране)' });
  assert(!(await app.exists(NO_WATER_HINT)), 'при воде в кадре нет «לא זוהו מים באזור שסומן…» (проверить сцену)');
  assert(!(await app.exists(PALE_HINT)), 'нет «בהירים מהרגיל»');
  await app.screenshot('ab4270-step2-pale-pool-green-continue-active');
  await app.restart();
}
